-- DRAWDOWN MISSION CREDITS: RECOVERY ONLY, PART 1 OF 2
-- Generated by tools/build-drawdown-credit-fallback.mjs from the frozen missions.json
-- (sha256 b9150c5b3075862fc66b989a12791278924414d2c6fc463fcb3dbbf67c6e6f66) and publication-policy.json.
-- Check with node tools/build-drawdown-credit-fallback.mjs --check. Applied SQL bytes never change.
--
-- RECOVERY ARTIFACT. Never a forward migration. Restore only after the publication is rolled back.
-- Apply this exact file with Supabase MCP apply_migration (it runs as postgres), then record its actual version.
-- Recovery requires separate authorization and verified permission before any later republication.
-- Both recovery parts are required to restore all 87 historical detail rows. They may run in either order.
-- Each part refuses unless all 125 Drawdown missions are drafts; no quotation is restored into a public mission.
-- The stored excerpts are historical recovery material, not permission evidence.
-- Exact before/after fingerprints reject concurrent or unexpected credit/source/license edits (55000); reruns do nothing.
-- No schema, grants, policies, original mission wording, proof hints, safety notes or assignments change.
-- Rollback files: 20261120050000_action_mission_drawdown_credit_fallback_01.rollback.sql, 20261120050000_action_mission_drawdown_credit_fallback_02.rollback.sql.
-- Proof: scripts/test/drawdown-credit-fallback.integration.mjs (isolated PostgreSQL), plus the root contract tests.
begin;
set local lock_timeout = '5s';
set local standard_conforming_strings = on;

do $drawdown_credit_fallback$
declare
  expected record;
  actual record;
  actual_md5 text;
  before_prefix text;
  after_prefix text;
begin
  -- Lock the existing catalog and missions in a stable order, including the 38 detail rows we preserve.
  perform d.mission_id from public.action_mission_details d
    join public.action_missions m on m.id = d.mission_id
    where d.catalog = 'drawdown' order by d.mission_id for update of d, m;
  if (select count(*) from public.action_mission_details d join public.action_missions m on m.id = d.mission_id
      where d.catalog = 'drawdown') <> 125 then
    raise exception 'Drawdown credit correction refused: expected all 125 imported missions and details' using errcode = '55000';
  end if;
  if exists (select 1 from public.action_mission_details d join public.action_missions m on m.id = d.mission_id
      where d.catalog = 'drawdown' and m.status <> 'draft') then
    raise exception 'Drawdown credit recovery refused: all 125 missions must be drafts' using errcode = '55000';
  end if;

  for expected in select * from (values
    ('02f26a02-9e16-50ff-aa3a-ff108aa9756c'::uuid, '48b7d491b0e7f01afd2d1170e8c91cb8', 'ad5532c4f1c35b4e56540361150cc039', 'We define Use Smart & Programmable Thermostats as reducing energy use and associated GHG emissions from heating and cooling by automatically making adjustments to the set temperature of a residential building.'),
    ('0b3adca4-63f1-50aa-a3d8-1fdd8426d787'::uuid, '05bade3f40dd0d3006c0bd288924acdd', 'caab0877cbf91fac5accea08fff68720', 'Electric scooters and motorcycles are battery-powered two- and three-wheeled vehicles that provide low-emissions mobility. This category of transport includes electric mopeds, motorbikes, seated motor scooters, motorcycles, and three-wheel vehicles, such as e-rickshaws and e-tuk-tuks.'),
    ('0cab1dcb-56e2-501d-87e4-bee9130bf456'::uuid, 'e9b1a121f19caac5e82135f2b3000949', '1a30612f93150527dcd72cd428be587d', 'Agrivoltaics is the dual use of land for simultaneous solar photovoltaic (PV) power generation and agricultural production. It reduces GHG emissions by shifting electricity production from fossil fuels to renewables. Agrivoltaic systems can be categorized by system type, PV configuration, module tilt, and agricultural activity. These systems operate at both utility and distributed scales.'),
    ('0f2c4e86-82a9-5e77-9998-68ddb3c337fa'::uuid, '8f1db7d4859a1d377c1a04bacfef3fa6', '694cbd213eb0b86045b26b7841035933', 'Cultivated meat is produced from a sample of animal cells, rather than by slaughtering animals. This technology shows promise for reducing emissions from animal agriculture, but its climate impact depends on the energy source used during production.'),
    ('12db7169-9d11-5a35-988c-d58c8d0a3c86'::uuid, '8e76d0e66592c2ef5fbf59a8af856881', '468c703635c4414adddaa42915d7afe7', 'Sustainable aviation fuel (SAF) is a low-carbon alternative to conventional jet fuel. It is made from renewable feedstocks, including waste oils, agricultural residues, and renewable electricity. However, when combustion emissions are considered, SAF does not consistently reduce emissions when compared to conventional fuels. SAF is already in use in commercial flights at low blending levels.'),
    ('1321d44c-b8ca-5f2e-975d-a7c1487d5cd0'::uuid, '5bad85d9f306e907bc72ff78708f282a', '06dc18081f86e576935c094c07d541af', 'Rice production is a significant source of methane emissions and a minor source of nitrous oxide emissions. Most rice production occurs in flooded fields called paddies, where anaerobic conditions trigger high levels of methane production. This solution includes two related practices that each reduce emissions from paddy rice production: noncontinuous flooding and nutrient management.'),
    ('14a40713-7381-5a28-8506-03b4df42f043'::uuid, '72b5351ca92ccc2a139fa3e57fc2527e', 'da46ba70c8954cd6d8c8add8f3ede121', 'Distributed solar photovoltaic (PV) systems are small-scale solar PV systems – usually under 1 MW, and installed near the point of use, such as on homes, businesses, or local facilities – that generate electricity for on-site consumption or local grid supply. This solution reduces reliance on centralized fossil-fuel power, cutting GHG emissions and minimizing transmission losses.'),
    ('154bc628-8758-51ed-924a-1dd61ed2e171'::uuid, 'c0c68a6570c4e64237cbaa79a548074c', 'b8b24671b4dbc3541670144dad0ce512', 'Contrails, the long, thin clouds that form behind airplanes, trap heat radiating from the Earth, creating a strong but short-lived warming effect similar to that of GHGs in the atmosphere (Kärcher, 2018; Thomas et al., 2025). Rerouting airplanes to avoid areas where warming contrails can form reduces the warming impact of these human-made clouds (Martin Frias et al., 2024).'),
    ('169089fe-4e2c-54b5-a91f-11fcde81d44d'::uuid, '44ed9758b64344e35e15c505666c051c', '011a49e322b8df14500386bb3b9f623d', 'Improving refrigerant management involves deploying practices and technologies that reduce the amount of climate-warming refrigerant chemicals escaping into the atmosphere from air conditioning, refrigeration, and heat pump equipment. This solution has two components: reducing refrigerant leaks during refrigerant charging and use, and recovering refrigerant to prevent its release from end-of-life equipment.'),
    ('1a9c8fcb-2a76-56de-b019-9c1f23a19800'::uuid, '50dcc5ab52e8996d8f4a9761f34ed60b', '51ca3b0f2974813b09e5cc85569be5f3', 'Enhanced rock weathering removes CO₂ from the air by accelerating the natural chemical and physical breakdown of certain rocks. This carbon removal practice can be effective and has been deployed in pilot and small-scale commercial projects.'),
    ('1b0ab594-ac54-5909-a768-a35e518a1449'::uuid, '1fdd08e6a7126dd03937992eced54d4a', '8b76265203e1aba293af492419f1afe6', 'Green roofs sequester carbon through photosynthesis and may reduce energy consumption and emissions from cooling and heating the building thanks to the added insulation and the cooling effects of plants (Getter et al., 2009; He et al., 2023).'),
    ('1ba35152-acfa-5786-8eb7-015bfa01c232'::uuid, 'fc8c1eecd9c385d11005d64297e74467', '8da925d207cf2a1e968b0d267653909a', 'Methane digesters are specialized devices that use anaerobic digestion to convert agricultural, industrial, or municipal organic waste into biogas and digestate, a nutrient-rich material. Treating organic waste using a methane digester reduces emissions by capturing methane that would have been released during uncontrolled anaerobic decomposition in a landfill or manure lagoon.'),
    ('1bd34e77-5d56-532f-8989-77f1bde20630'::uuid, '19640f82bff2184d6f91733d88fafbba', '96d623dc0dade4b6c12ab067b0547f1a', 'Nuclear fusion combines two elements in a nuclear reaction to form a larger element and release energy that can be used to generate electricity. Nuclear fusion has been researched since the 1950s, but there have been no nuclear fusion plants built to date.'),
    ('1c2eaace-0753-5afa-b538-dc8989ed529e'::uuid, '3006507239e9a806fc113a3ad6f8a611', '5ebc0ce0100e2547a1d435a14fad48fa', 'We define the Deploy Silvopasture solution as the adoption of agroforestry practices that add trees to grazing land, including planted pastures and natural rangelands. (Note that this solution does NOT include creating forested grazing land by thinning existing forest; this is a form of deforestation and not desirable in terms of climate.)'),
    ('216568f0-243f-5cac-91b9-4b4ae8b571ed'::uuid, '4bd9efa2e5553f2531e9c3bcdd6450c4', '38556d79743a794232d0a2a27ed3f18e', 'Forest restoration is the process of returning previously forested land to a forested state. As forests regrow, they remove carbon from the atmosphere and sequester it in biomass.'),
    ('22458ffa-9f2e-5a40-b72f-921a3a09b5a0'::uuid, '3011a1bf223aa36b8b6d1794a63d551c', 'b27dc5317149133fb6d05f96556f97e2', 'Feed additives can reduce enteric methane production in ruminant livestock, such as cattle, goats, and sheep. Most feed additive compounds are still being researched to determine their efficacy and safety; however, at least one product, 3-NOP (3-nitrooxypropanol), has been shown to be effective, has recently been approved for use in many countries, and has experienced some early adoption.'),
    ('237b2be1-b651-5f68-9af3-f26076bb823b'::uuid, '31d09a7a0e186961e4269d369891ab44', '24b1984dee7696d7e4b0c23145fe801d', 'Deploy Alternative Insulation Materials is defined as using alternative building insulation materials in place of conventional ones. In particular, we highlight the impact of using cellulose instead of glass, mineral, or plastic insulation in new and retrofit buildings.'),
    ('29222f7a-28ca-54ba-970f-bbef5c525b0f'::uuid, '7100eaa4a0946cf244854e70c5f1b99c', 'ef3a06261afc988d0530a9548d3d7841', 'Bioplastics are renewable, plant-based alternatives to conventional plastics that can reduce emissions by replacing fossil-based feedstocks with biogenic carbon feedstocks. These feedstocks are biomass materials that absorb atmospheric CO₂ during growth and serve as the carbon source for plastic production.'),
    ('2bab59bf-f317-5962-bdaa-2ee1ebbb664a'::uuid, '97272ac4c9dbc88f892bb5caba31b63d', '9adfab85413f79d485a867f2a3e487a1', 'Reducing grazing intensity involves lowering ruminant livestock stocking rates or grazing pressure. This removes carbon from the atmosphere by reducing land damage and increasing soil organic carbon (SOC).'),
    ('31490c0d-4a7a-5e86-a3a7-9904e1b872ad'::uuid, '4670696432ea2df8931bc2c963923583', 'eca08ca1467fee33279685e4adc32374', 'Project Drawdown’s Improve Annual Cropping solution is a set of practices that protects soils by minimizing plowing (no-till/reduced tillage) and maintaining continuous soil cover (by retaining crop residues or growing cover crops). This increases soil carbon sequestration and reduces nitrous oxide emissions.'),
    ('34dcd492-e437-500b-8818-fd9dfaa3fbbc'::uuid, '90a163cec19961d4d1cac5e9a6ccf693', 'd90ed79e1ffafab39b79c947375ba547', 'Recycling is a mechanical process that repurposes waste into new products without altering their chemical structure. This solution focuses on four common waste types: metals, paper and cardboard, plastics, and glass. It reduces GHG emissions by minimizing reliance on energy-intensive primary material production, reducing demand for raw materials, and diverting paper from landfills, where decomposition can produce methane.'),
    ('38f5c62c-a8cb-5ac4-b0b1-aba602a400d5'::uuid, '7a075f152c4f1d379707fb923f18c5d4', '2286bdb355cae02b750d8c8725228753', 'Reduce Overfishing refers to the use of management actions that decrease fishing effort and therefore cut CO₂ emissions from fishing vessel fuel use on overfished stocks. Advantages include the potential to replenish depleted fish stocks, support ecosystem health, and enhance long-term food and job security.'),
    ('3933adb5-41e2-57fc-9f40-a2cf8f7ab0f4'::uuid, '175c2879f05b8530a47454841bbba445', 'f545dc76129f29b970e011178a79a57a', 'Ocean alkalinity enhancement (OAE) increases the ocean’s natural ability to remove CO₂ from the air by increasing the alkalinity of ocean water. This carbon removal practice could be globally effective at removing CO₂ at the gigaton level annually and is currently being tested in field studies.'),
    ('39c075dc-ce16-5321-b1d7-5b75b916a3cb'::uuid, '11fde878f3f702d5e831493f770ae1bc', '32837f3d957c00bb3bfee18aa4d7f68a', 'In this solution, green hydrogen replaces fossil fuel–based hydrogen for use as a feedstock in the production of more complex molecules such as ammonia for fertilizers and methanol for the production of other commodity chemicals. Green hydrogen production in this solution uses on-site renewable electricity or off-site renewable electricity that directly supplies the facility.'),
    ('3a9da222-581a-51ec-b5ae-a2599c35f46d'::uuid, '2f99d8c42da849c3c9f6b7933f861ea6', '82a6fdf7c81ec35b4141721e2b6abca9', 'Boosting the efficiency of appliances and equipment cuts GHG emissions by reducing the amount of electricity used to operate these devices. Efficiency improvements also lead to reduced peak demand, less strain on the electric grid, and potential utility savings for homeowners due to reduced electricity use.'),
    ('3f646f9c-5619-54ed-b38a-3977d359c61c'::uuid, '0cda1223a3462012d2fdc9f2e9358194', '304f6936b1abf6213965cdeeb95b42ea', 'Reintroducing or increasing the populations of large wild herbivores – such as bison, elephants, and moose – in natural and degraded ecosystems alters habitats, potentially leading to greater carbon removal from the atmosphere and increased carbon storage in vegetation and soils. However, evidence of its effectiveness is limited and mixed.'),
    ('3fb16043-b210-577e-b662-670cb9df0296'::uuid, 'f21ce76529f1c2329c901702691330da', '9b214ac8410b7449a4fd42abb571dc45', 'Improving district heating for industry involves using low-carbon alternatives, such as electric boilers, heat pumps, and waste heat from other industries, to provide heat to industries for their operations. Currently, most district heating for industry relies heavily on fossil fuels to generate heat (International Energy Agency [IEA], 2026).'),
    ('400c34d6-e2d4-5977-84a6-21373c17f230'::uuid, '44638c26d2710dc57704d4dbaf307374', '36692ca95b2da724dc5ee87bc2436612', 'Onshore wind turbines are land-based machines that harness natural wind to generate electricity. Electricity generation from wind turbines depends on many factors, including natural wind speeds, consistency, and directionality. The Deploy Onshore Wind Turbines solution focuses on utility-scale electricity generation above 1 MW in rated capacity, generally from fields of turbines called wind farms.'),
    ('4a35883c-a97e-5422-bd31-c5a6e4763554'::uuid, '96120b57a3b3df06f616121b88d10fa7', '2b22b5c822e43f6467ddfa74abc65a76', 'Green hydrogen is an emissions-free fuel produced by using renewable electricity to split water into hydrogen and oxygen. For aviation and long-haul trucking, green hydrogen can be used either directly in fuel cells or combusted in modified engines, offering a potential pathway to deep emissions reductions.'),
    ('4f17538c-53b5-5c0e-9a9a-2d8ff007990f'::uuid, '5dd4784b00d41875cd949bf7542d7f90', '2590df92b46ffa6fee9fafc244fc51a7', 'Electric cooking equipment such as electric resistance stoves, induction stoves, and electric ovens can replace fuel-burning cooking equipment and reduce cooking-related GHG emissions, especially in regions with low-emission electricity grids. Cooking with electricity has significant health, safety, and energy efficiency benefits but cost, reliable access to electricity, and cultural compatibility are barriers to adoption.'),
    ('56b4c743-10a0-5148-ae60-323c3e0d1564'::uuid, 'd801bbb2bb9474e0b9f3ca031e7503f9', '9a319964056fc7538985aa84e472383c', 'Improving fishing vessel efficiency cuts CO₂ emissions in wild capture fisheries by lowering fuel use through vessel, gear, or operational modifications. Advantages include the long-term cost savings from fuel use reductions, the ability to implement many of these improvements without reducing fishing effort, and the potential additional benefits for air quality and marine ecosystems.'),
    ('5a898376-c3f7-57b3-9029-be155f809f2f'::uuid, 'cceaa01d919049e35814a43ffc02f734', '07935b37112973903a9c06805c95bed4', 'Coastal wetland protection is the long-term protection of mangrove, salt marsh, and seagrass ecosystems from degradation by human activities. This solution focuses on legal mechanisms of coastal wetland protection, including the establishment of Protected Areas (PAs) and Marine Protected Areas (MPAs), which are managed with the primary goal of conserving nature.'),
    ('5b79bc68-40a5-5a3a-835f-23ab6b83e99e'::uuid, '756fbc74513244cc1e1ec5e327aec950', '2f80c6368910e7156f5ba912cc0397db', 'Peatland restoration is the process of returning peat-forming vegetation and natural hydrologic conditions to degraded peatlands. Restoration of peatlands stops GHG emissions from peat degradation and removes carbon through sequestration in biomass and peat.'),
    ('5ce73068-1f93-55dd-a858-c36c2ebeb612'::uuid, '5a3242a56c8235c7c9990145c255ab20', '9230e1549d4bb05b1e3aaf07bca29675', 'Landfill management is the process of reducing methane emissions from landfill gas (LFG). As bacteria break down organic waste in an environment without oxygen, they produce methane and release it into the atmosphere if there are no controls in place. This solution focuses on two methane abatement strategies: 1) methane capture/use/destruction and 2) biocovers.'),
    ('60df48e0-d185-5852-99ae-7bf2a245e853'::uuid, 'd373b35f9662a4a85d950ae114ffeb53', '3eba59dfd84950b3e63e54c2668c4529', 'Producing biochar is the process of taking organic matter such as crop residues, animal manure, and forest residues and converting it into a charcoal-like substance known as biochar. Producing biochar removes carbon from the atmosphere by transforming carbon absorbed by plants and animals into a highly stable form, preventing it from quickly returning to the atmosphere (Belmont & Sanchez, 2025).'),
    ('69a6d95a-447b-5cdc-9d60-064b8dc01d6f'::uuid, 'e97adb65efaa0dd8e73b44349185e86b', '582304ebc12a44ab160eec894e96aa7c', 'Carpooling entails increasing the occupancy of passenger cars, including taxis, pickup trucks, motorhomes, passenger vans and other such vehicles but not including two- or three-wheeled, freight, public transit, or commercial vehicles, such as buses, heavy trucks, and commercial vans. It replaces the practice of driving alone.'),
    ('6b7e9acb-e697-56e8-beb4-417333d2c5db'::uuid, 'cc51814f414f769bb893948c9a0befac', '823932d9b82e6e2c7bacec4008864ca0', 'We define the Mobilize Electric Bicycles solution as increased travel by bicycles that have an electric motor to supplement the effort of the rider, but require the rider to turn the pedals to activate the motor.'),
    ('6fae6f0d-c160-57ef-9977-3bed661fb77a'::uuid, 'a97e5fa4f343c02010d8fca76f10c8c4', '1e7a86c7225fb0b6873e36cd56a56727', 'We define the Improve Nutrient Management solution as reducing excessive nitrogen use on croplands. Nitrogen is critical for crop production and is added to croplands as synthetic or organic fertilizers and through microbial activity. However, farmers often add more nitrogen to croplands than crops can use.'),
    ('728a63c6-8282-5cf3-91c6-90578935883d'::uuid, 'd02bcfbf7094585c6ed2d186b07015b7', '3e80cf8bbeddc45375adced78343cbfd', 'Micro wind turbines harness natural wind to generate electricity. They can operate independently or be connected to a centralized electricity grid, and are useful for small-scale commercial, agricultural, and residential applications. Advantages include reducing reliance on fossil fuels for electricity generation, potential expansion of electrification to rural areas, and improvement in energy equity and independence worldwide.'),
    ('72c015b4-1c69-50d5-adee-2264d5fd2a53'::uuid, '3c29dd0c5d9d1883ec0a2bbe0443c49e', '9087d7d46746f8de6eeab4afdfa02868', 'A district heating system provides space and water heating to a large number of buildings through an underground distribution system.'),
    ('747455c5-6ce7-5aa0-9363-e3dd41f8e954'::uuid, 'bd8b4e4d728b6003af0a76ee2819c2a0', '0d682c9198ecd327008da2228fd11804', 'Whales play a critical role in the ocean carbon cycle, but commercial whaling in the 20th century drastically diminished their populations. Restoring the abundance of whales to pre-whaling levels has been proposed as a way to remove additional CO₂ from the atmosphere and store it in the ocean.'),
    ('74a7935a-731f-5f35-ad12-f1799e22d378'::uuid, '8c36ef1e809c032e6394fd8af9a48ca2', '746522f716e876a987e483abcc5800bc', 'Restore Mangrove Ecosystems removes carbon by re-establishing mangrove forests in areas where they were previously destroyed by conversion or other disturbances. This allows carbon to accumulate in above- and below-ground biomass and sediment. Advantages include mangrove forests'' high effectiveness at carbon removal and storage, as well as their numerous environmental benefits and generally low cost.'),
    ('78ab0a5d-ca2b-52b2-a9d0-54827b5f3fd7'::uuid, '19ed112bf4c480cf8347abd69d477c90', 'a5aaa900af9ab688396b2b8194cbe8a6', 'Restore Seagrass Ecosystems involves reestablishing seagrass meadows in ocean areas where they were lost due to disturbances or degradation. As seagrasses grow, they remove CO₂ from ocean water through photosynthesis and accumulate carbon in their biomass, which allows seawater to take up additional CO₂ from the atmosphere.'),
    ('7bf1aab9-7278-547d-810b-df442bb1eb04'::uuid, '17aa3b8baaec3b85aadd85c1e402d033', 'f0d57471db74b73254dc060d15104e67', 'We define Deploy Building Automation Systems (BASs) as reducing commercial (i.e., nonresidential or industrial) building energy use and associated GHG emissions by using sensors to monitor a building in operation and control systems such as heating, cooling, ventilation, plug loads, and lighting for the purpose of saving energy.')
  ) as v(id, before_md5, after_md5, original_about) order by id loop
    select d.* into actual from public.action_mission_details d
      where d.mission_id = expected.id and d.catalog = 'drawdown';
    if not found then
      raise exception 'Drawdown credit correction refused: missing target %', expected.id using errcode = '55000';
    end if;
    actual_md5 := md5(coalesce(actual.credit_line, '') || chr(31) || coalesce(actual.about, '') || chr(31) || coalesce(actual.about_credit, '') || chr(31) || coalesce(actual.source_url, '') || chr(31) || coalesce(actual.license_name, '') || chr(31) || coalesce(actual.license_url, '') || chr(31) || coalesce(actual.doi, ''));
    if actual_md5 = expected.before_md5 then continue; end if;
    if actual_md5 <> expected.after_md5 then
      raise exception 'Drawdown credit correction refused: credit or source changed for %', expected.id using errcode = '55000';
    end if;
    before_prefix := 'Solution summary from Project Drawdown (' || actual.source_url || '), used with permission';
    after_prefix := 'Solution listed in Project Drawdown''s Explorer (' || actual.source_url || ')';
    if left(actual.credit_line, length(after_prefix)) <> after_prefix then
      raise exception 'Drawdown credit correction refused: unexpected credit prefix for %', expected.id using errcode = '55000';
    end if;
    update public.action_mission_details
      set credit_line = before_prefix || substr(actual.credit_line, length(after_prefix) + 1),
          about = expected.original_about,
          about_credit = 'Solution summary © Project Drawdown, used with permission.',
          updated_at = now()
      where mission_id = expected.id;
    select md5(coalesce(d.credit_line, '') || chr(31) || coalesce(d.about, '') || chr(31) || coalesce(d.about_credit, '') || chr(31) || coalesce(d.source_url, '') || chr(31) || coalesce(d.license_name, '') || chr(31) || coalesce(d.license_url, '') || chr(31) || coalesce(d.doi, '')) into actual_md5 from public.action_mission_details d where d.mission_id = expected.id;
    if actual_md5 <> expected.before_md5 then
      raise exception 'Drawdown credit correction refused: resulting fingerprint differs for %', expected.id using errcode = '55000';
    end if;
  end loop;

end
$drawdown_credit_fallback$;

commit;
